// src/components/Dashboard.js
import React from 'react';
import { useNavigate } from 'react-router-dom';
import '../App.css';

const Dashboard = ({ user }) => {
  const navigate = useNavigate();

  return (
    <div className="container">
      <div className="upload-card" style={{ padding: '2rem', borderRadius: '12px' }}>
        {/* Top centered greeting */}
        <h1 className="title text-center">Hello, {user?.name}!</h1>
        <p className="subtitle text-center mb-5">Choose the type of area you want to monitor</p>

        {/* Two-column section below greeting */}
        <div
          className="area-sections"
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            gap: '2rem',
            flexWrap: 'wrap',
          }}
        >
          {/* Prohibited Area */}
          <div
            className="area-card"
            style={{
              flex: '1',
              minWidth: '300px',
              backgroundColor: '#fffaf2',
              padding: '1.5rem',
              borderRadius: '12px',
              boxShadow: '0 6px 12px rgba(255, 140, 0, 0.1)',
            }}
          >
            <h3 style={{ color: '#ff8c00' }}>Prohibited Area</h3>
            <ul style={{ paddingLeft: '1.2rem', lineHeight: '1.6' }}>
              <li>Standard surveillance zone</li>
              <li>Moderate security level</li>
              <li>Human detection active</li>
            </ul>
            <button
              className="submit-button mt-3 w-100"
              onClick={() => navigate('/prohibited-area')}
            >
              Monitor Prohibited Area
            </button>
          </div>

          {/* Strictly Prohibited Area */}
          <div
            className="area-card"
            style={{
              flex: '1',
              minWidth: '300px',
              backgroundColor: '#fffaf2',
              padding: '1.5rem',
              borderRadius: '12px',
              boxShadow: '0 6px 12px rgba(255, 140, 0, 0.1)',
            }}
          >
            <h3 style={{ color: '#d32f2f' }}>Strictly Prohibited Area</h3>
            <ul style={{ paddingLeft: '1.2rem', lineHeight: '1.6' }}>
              <li>High-security surveillance</li>
              <li>Instant alert on intrusions</li>
              <li>Real-time tracking enforced</li>
            </ul>
            <button
              className="submit-button mt-3 w-100"
              onClick={() => navigate('/strictly-prohibited-area')}
            >
              Monitor Strictly Prohibited Area
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
